import sys

MOD = 10**9 + 7

def countPalindromicPaths(matrix):
    n = len(matrix)
    m = len(matrix[0])
    dp = [[[0] * (n + m) for _ in range(m)] for _ in range(n)]
    dp[0][0][0] = 1

    for i in range(n):
        for j in range(m):
            for k in range(n + m - 1):
                if i > 0:
                    dp[i][j][k] += dp[i - 1][j][k]
                    if k >= 1 and matrix[i][j] == matrix[i - 1][j]:
                        dp[i][j][k] += dp[i - 1][j][(k - 1) // 2]
                if j > 0:
                    dp[i][j][k] += dp[i][j - 1][k]
                    if k >= 1 and matrix[i][j] != matrix[i][j - 1]:
                        dp[i][j][k] += dp[i][j - 1][(k - 1) // 2]
                dp[i][j][k] %= MOD

    return dp[n - 1][m - 1][(n + m - 1) // 2] % MOD

